def erstelle_bericht(*werte, **optionen):
    """
    Erstellt einen Statistikbericht ueber beliebig viele Zahlen.
    Eingabe:
    - werte: beliebig viele Zahlen (positional arguments, landen in einem tuple)
    - optionen: keyword arguments mittelwert, max, min, anzahl (jeweils True/False)
    Rueckgabe: String mit einer Zeile pro gesetzter Option
    """
    if len(werte) == 0:
        return "Keine Zahlen uebergeben!"

    bericht = ""
    if optionen.get("mittelwert", False):
        bericht = bericht + "Mittelwert: " + str(round(sum(werte) / len(werte), 2)) + "\n"
    if optionen.get("max", False):
        bericht = bericht + "Max: " + str(max(werte)) + "\n"
    if optionen.get("min", False):
        bericht = bericht + "Min: " + str(min(werte)) + "\n"
    if optionen.get("anzahl", False):
        bericht = bericht + "Anzahl: " + str(len(werte)) + "\n"
    return bericht

