def spiele_hoechste_karte(karten, preiskarte):
    """Strategie: spielt die hoechste Karte auf der Hand."""
    return max(karten)

def spiele_niedrigste_karte(karten, preiskarte):
    """Strategie: spielt die niedrigste Karte auf der Hand."""
    return min(karten)

STRATEGIEN = {"hoch": spiele_hoechste_karte,
              "niedrig": spiele_niedrigste_karte}

def hole_strategie(name):
    """
    Liefert die zum Namen passende Strategie-Funktion.
    Unbekannte Namen ergeben spiele_niedrigste_karte.
    """
    return STRATEGIEN.get(name, spiele_niedrigste_karte)

def spiele_runde(karten1, karten2, preiskarte, strategie1, strategie2):
    """
    Wertet eine Goofspiel-Runde aus.
    Eingabe:
    - karten1, karten2: Listen mit den Handkarten
    - preiskarte: Zahl - Wert der aufgedeckten Preiskarte
    - strategie1, strategie2: Funktionen (karten, preiskarte) -> Karte
    Rueckgabe: Tupel (punkte_spieler1, punkte_spieler2) fuer diese Runde
    """
    karte1 = strategie1(karten1, preiskarte)
    karte2 = strategie2(karten2, preiskarte)
    if karte1 > karte2:
        return (preiskarte, 0)
    elif karte2 > karte1:
        return (0, preiskarte)
    else:
        return (0, 0)
